const Typesense = require('typesense');
const fs = require('fs');

async function test() {
  const apiKey = fs.readFileSync('/etc/typesense-api-key', 'utf8').trim();
  const client = new Typesense.Client({
    'nodes': [{
      'host': '127.0.0.1',
      'port': '8108',
      'protocol': 'http'
    }],
    'apiKey': apiKey,
    'connectionTimeoutSeconds': 2
  });

  try {
    // Delete collection if exists
    try {
      await client.collections('products').delete();
      console.log('Deleted existing products collection');
    } catch (e) {}

    // Create collection
    const schema = {
      name: 'products',
      fields: [
        { name: 'name', type: 'string' },
        { name: 'category', type: 'string', facet: true },
        { name: 'price', type: 'float' }
      ]
    };
    await client.collections().create(schema);
    console.log('Created products collection');

    // Load baseline
    const baseline = JSON.parse(fs.readFileSync('/home/user/saved-search-alerts/data/baseline.json', 'utf8'));
    await client.collections('products').documents().import(baseline, { action: 'upsert' });
    console.log('Imported baseline');

    // Test search 1: empty query
    let res = await client.collections('products').documents().search({
      q: '*',
      query_by: 'name',
      per_page: 250
    });
    console.log('Search * hits:', res.hits.map(h => h.document.id));

    // Test search 2: query "Wireless"
    res = await client.collections('products').documents().search({
      q: 'Wireless',
      query_by: 'name',
      per_page: 250
    });
    console.log('Search "Wireless" hits:', res.hits.map(h => h.document.id));

    // Test search 3: category filter exact match
    res = await client.collections('products').documents().search({
      q: '*',
      query_by: 'name',
      filter_by: 'category:=[electronics]',
      per_page: 250
    });
    console.log('Search category "electronics" hits:', res.hits.map(h => h.document.id));

    // Test search 4: price filter
    res = await client.collections('products').documents().search({
      q: '*',
      query_by: 'name',
      filter_by: 'price:<=40',
      per_page: 250
    });
    console.log('Search price <= 40 hits:', res.hits.map(h => h.document.id));

    // Test search 5: combined
    res = await client.collections('products').documents().search({
      q: '*',
      query_by: 'name',
      filter_by: 'category:=[toys] && price:<=35',
      per_page: 250
    });
    console.log('Search category "toys" && price <= 35 hits:', res.hits.map(h => h.document.id));

  } catch (err) {
    console.error('Error:', err);
  }
}

test();

const express = require('express');
const cors = require('cors');
const fs = require('fs');
const path = require('path');
const Typesense = require('typesense');

const app = express();
const PORT = 8080;

app.use(cors());
app.use(express.json());

// Serve static frontend files from 'public' directory
app.use(express.static(path.join(__dirname, 'public')));

// Load Typesense API key
const apiKey = fs.readFileSync('/etc/typesense-api-key', 'utf8').trim();

// Initialize Typesense Client
const typesenseClient = new Typesense.Client({
  'nodes': [{
    'host': '127.0.0.1',
    'port': '8108',
    'protocol': 'http'
  }],
  'apiKey': apiKey,
  'connectionTimeoutSeconds': 5
});

const SAVED_SEARCHES_FILE = path.join(__dirname, 'data', 'saved_searches.json');

// Helper to load saved searches
function loadSavedSearches() {
  try {
    if (fs.existsSync(SAVED_SEARCHES_FILE)) {
      const data = fs.readFileSync(SAVED_SEARCHES_FILE, 'utf8');
      return JSON.parse(data);
    }
  } catch (err) {
    console.error('Error loading saved searches:', err);
  }
  return [];
}

// Helper to save saved searches
function saveSavedSearches(searches) {
  try {
    fs.writeFileSync(SAVED_SEARCHES_FILE, JSON.stringify(searches, null, 2), 'utf8');
  } catch (err) {
    console.error('Error saving saved searches:', err);
  }
}

// Helper to format saved search for public response (exactly the required keys)
function formatSavedSearch(search) {
  return {
    id: search.id,
    name: search.name,
    q: search.q,
    category: search.category,
    max_price: search.max_price,
    match_count: search.match_count,
    new_count: search.new_count
  };
}

// Helper to query Typesense for all matching document IDs
async function getAllMatchingIds(q, category, max_price) {
  const query = (q && q.trim() !== '') ? q : '*';
  const filters = [];
  if (category && category.trim() !== '') {
    filters.push(`category:=[${category}]`);
  }
  if (max_price !== null && max_price !== undefined) {
    filters.push(`price:<=${max_price}`);
  }
  const filter_by = filters.join(' && ');

  let page = 1;
  const perPage = 250;
  const ids = [];

  while (true) {
    const searchParams = {
      q: query,
      query_by: 'name',
      filter_by: filter_by || undefined,
      per_page: perPage,
      page: page
    };

    const res = await typesenseClient.collections('products').documents().search(searchParams);
    const pageIds = res.hits.map(hit => hit.document.id);
    ids.push(...pageIds);

    if (ids.length >= res.found || pageIds.length < perPage) {
      break;
    }
    page++;
  }

  return ids;
}

// Ensure products collection exists and baseline is indexed on startup
async function initTypesense() {
  try {
    // Check if collection exists
    let exists = true;
    try {
      await typesenseClient.collections('products').retrieve();
      console.log('Collection "products" already exists.');
    } catch (err) {
      exists = false;
    }

    if (!exists) {
      const schema = {
        name: 'products',
        fields: [
          { name: 'name', type: 'string' },
          { name: 'category', type: 'string', facet: true },
          { name: 'price', type: 'float' }
        ]
      };
      await typesenseClient.collections().create(schema);
      console.log('Created "products" collection.');
    }

    // Index baseline catalog
    const baselinePath = path.join(__dirname, 'data', 'baseline.json');
    if (fs.existsSync(baselinePath)) {
      const baselineDocs = JSON.parse(fs.readFileSync(baselinePath, 'utf8'));
      await typesenseClient.collections('products').documents().import(baselineDocs, { action: 'upsert' });
      console.log(`Indexed baseline catalog of ${baselineDocs.length} products.`);
    } else {
      console.warn('Baseline catalog file not found at', baselinePath);
    }
  } catch (err) {
    console.error('Error initializing Typesense:', err);
  }
}

// API Endpoints

// GET /api/catalog - Helper endpoint to get the ingest catalog for the UI
app.get('/api/catalog', (req, res) => {
  try {
    const catalogPath = path.join(__dirname, 'data', 'catalog.json');
    if (fs.existsSync(catalogPath)) {
      const catalog = JSON.parse(fs.readFileSync(catalogPath, 'utf8'));
      res.json(catalog);
    } else {
      res.status(404).json({ error: 'Catalog file not found' });
    }
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// GET /api/saved-searches
app.get('/api/saved-searches', (req, res) => {
  const searches = loadSavedSearches();
  res.json(searches.map(formatSavedSearch));
});

// POST /api/saved-searches
app.post('/api/saved-searches', (req, res) => {
  const { name, q, category, max_price } = req.body;

  if (typeof name !== 'string' || name.trim() === '') {
    return res.status(400).json({ error: 'Name is required' });
  }

  const searches = loadSavedSearches();
  const id = 'ss_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5);

  const newSearch = {
    id,
    name,
    q: q || '',
    category: category || '',
    max_price: max_price === undefined ? null : max_price,
    match_count: null,
    new_count: null,
    last_checked_ids: null // internal field
  };

  searches.push(newSearch);
  saveSavedSearches(searches);

  res.status(201).json(formatSavedSearch(newSearch));
});

// POST /api/saved-searches/{id}/check
app.post('/api/saved-searches/:id/check', async (req, res) => {
  const { id } = req.params;
  const searches = loadSavedSearches();
  const searchIndex = searches.findIndex(s => s.id === id);

  if (searchIndex === -1) {
    return res.status(404).json({ error: 'Saved search not found' });
  }

  const search = searches[searchIndex];

  try {
    const currentIds = await getAllMatchingIds(search.q, search.category, search.max_price);
    const currentCount = currentIds.length;

    let newCount = 0;
    if (search.last_checked_ids === null || search.last_checked_ids === undefined) {
      newCount = 0;
    } else {
      const lastSet = new Set(search.last_checked_ids);
      for (const cid of currentIds) {
        if (!lastSet.has(cid)) {
          newCount++;
        }
      }
    }

    // Update state
    search.match_count = currentCount;
    search.new_count = newCount;
    search.last_checked_ids = currentIds;

    searches[searchIndex] = search;
    saveSavedSearches(searches);

    res.json(formatSavedSearch(search));
  } catch (err) {
    console.error('Error checking saved search:', err);
    res.status(500).json({ error: err.message });
  }
});

// POST /api/check-all
app.post('/api/check-all', async (req, res) => {
  const searches = loadSavedSearches();
  const updatedSearches = [];

  try {
    for (const search of searches) {
      const currentIds = await getAllMatchingIds(search.q, search.category, search.max_price);
      const currentCount = currentIds.length;

      let newCount = 0;
      if (search.last_checked_ids === null || search.last_checked_ids === undefined) {
        newCount = 0;
      } else {
        const lastSet = new Set(search.last_checked_ids);
        for (const cid of currentIds) {
          if (!lastSet.has(cid)) {
            newCount++;
          }
        }
      }

      search.match_count = currentCount;
      search.new_count = newCount;
      search.last_checked_ids = currentIds;

      updatedSearches.push(search);
    }

    saveSavedSearches(updatedSearches);
    res.json(updatedSearches.map(formatSavedSearch));
  } catch (err) {
    console.error('Error checking all saved searches:', err);
    res.status(500).json({ error: err.message });
  }
});

// POST /api/ingest
app.post('/api/ingest', async (req, res) => {
  const { documents } = req.body;

  if (!Array.isArray(documents)) {
    return res.status(400).json({ error: 'documents must be an array' });
  }

  try {
    if (documents.length > 0) {
      await typesenseClient.collections('products').documents().import(documents, { action: 'upsert' });
    }
    res.json({ ingested: documents.length });
  } catch (err) {
    console.error('Error ingesting documents:', err);
    res.status(500).json({ error: err.message });
  }
});

// Start server after initializing Typesense
async function start() {
  await initTypesense();
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

start();

document.addEventListener('DOMContentLoaded', () => {
  // Elements
  const saveSearchForm = document.getElementById('save-search-form');
  const searchNameInput = document.getElementById('search-name');
  const searchQInput = document.getElementById('search-q');
  const searchCategoryInput = document.getElementById('search-category');
  const searchMaxPriceInput = document.getElementById('search-max-price');

  const catalogList = document.getElementById('catalog-list');
  const ingestAllBtn = document.getElementById('ingest-all-btn');

  const searchesList = document.getElementById('searches-list');
  const checkAllBtn = document.getElementById('check-all-btn');

  const toast = document.getElementById('toast');
  const toastMessage = document.getElementById('toast-message');

  // State
  let savedSearches = [];
  let catalogItems = [];
  const ingestedIds = new Set(); // Track ingested IDs in current session

  // Show Toast Notification
  function showToast(message, type = 'success') {
    toastMessage.textContent = message;
    if (type === 'error') {
      toast.className = 'fixed bottom-5 right-5 transform translate-y-0 opacity-100 transition-all duration-300 bg-red-600 text-white px-4 py-3 rounded-lg shadow-lg flex items-center gap-2 text-sm z-50';
    } else {
      toast.className = 'fixed bottom-5 right-5 transform translate-y-0 opacity-100 transition-all duration-300 bg-slate-900 text-white px-4 py-3 rounded-lg shadow-lg flex items-center gap-2 text-sm z-50';
    }

    setTimeout(() => {
      toast.className = 'fixed bottom-5 right-5 transform translate-y-20 opacity-0 transition-all duration-300 bg-slate-900 text-white px-4 py-3 rounded-lg shadow-lg flex items-center gap-2 text-sm z-50';
    }, 3000);
  }

  // Fetch Saved Searches
  async function fetchSavedSearches() {
    try {
      const res = await fetch('/api/saved-searches');
      if (!res.ok) throw new Error('Failed to fetch saved searches');
      savedSearches = await res.json();
      renderSavedSearches();
    } catch (err) {
      console.error(err);
      showToast('Error loading saved searches', 'error');
    }
  }

  // Fetch Ingest Catalog
  async function fetchCatalog() {
    try {
      const res = await fetch('/api/catalog');
      if (!res.ok) throw new Error('Failed to fetch catalog');
      catalogItems = await res.json();
      renderCatalog();
    } catch (err) {
      console.error(err);
      showToast('Error loading catalog', 'error');
    }
  }

  // Render Saved Searches
  function renderSavedSearches() {
    if (savedSearches.length === 0) {
      searchesList.innerHTML = `
        <div class="text-center py-12 text-slate-400">
          <svg class="w-12 h-12 mx-auto text-slate-300 mb-3" fill="none" stroke="currentColor" stroke-width="1.5" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path>
          </svg>
          <p class="text-sm font-medium">No saved searches yet</p>
          <p class="text-xs text-slate-400 mt-1">Create one using the form on the left.</p>
        </div>
      `;
      return;
    }

    searchesList.innerHTML = savedSearches.map(search => {
      const isChecked = search.match_count !== null;

      // Build filters display
      const criteria = [];
      criteria.push(`Query: <strong class="text-slate-900">"${search.q || '*'}"</strong>`);
      if (search.category) {
        criteria.push(`Category: <strong class="text-slate-900">"${search.category}"</strong>`);
      }
      if (search.max_price !== null) {
        criteria.push(`Max Price: <strong class="text-slate-900">$${search.max_price}</strong>`);
      }

      // Badge for new matches
      let badgeHtml = '';
      if (isChecked) {
        if (search.new_count > 0) {
          badgeHtml = `
            <span class="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-semibold bg-rose-100 text-rose-800 border border-rose-200 shadow-sm animate-pulse">
              <span class="w-1.5 h-1.5 rounded-full bg-rose-500"></span>
              +${search.new_count} new
            </span>
          `;
        } else {
          badgeHtml = `
            <span class="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-medium bg-slate-100 text-slate-600 border border-slate-200">
              0 new
            </span>
          `;
        }
      } else {
        badgeHtml = `
          <span class="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-medium bg-amber-50 text-amber-700 border border-amber-200">
            Unchecked
          </span>
        `;
      }

      return `
        <div class="p-4 rounded-xl border border-slate-200 hover:border-slate-300 bg-slate-50/50 transition-all flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div class="space-y-1.5">
            <div class="flex items-center gap-3 flex-wrap">
              <h3 class="font-bold text-slate-900 text-base">${search.name}</h3>
              ${badgeHtml}
            </div>
            <div class="text-xs text-slate-600 flex flex-wrap items-center gap-x-3 gap-y-1">
              ${criteria.join(' <span class="text-slate-300">|</span> ')}
            </div>
          </div>

          <div class="flex items-center gap-3 shrink-0 self-end sm:self-center">
            <div class="text-right sm:text-right flex flex-col justify-center">
              <span class="text-xs text-slate-500 uppercase tracking-wider font-semibold">Matches</span>
              <span class="text-lg font-extrabold text-slate-900">
                ${isChecked ? search.match_count : '—'}
              </span>
            </div>
            <button data-id="${search.id}" class="check-single-btn inline-flex items-center justify-center p-2 rounded-lg border border-slate-300 bg-white hover:bg-slate-50 text-slate-700 hover:text-slate-900 transition-colors shadow-sm" title="Check matches">
              <svg class="w-5 h-5" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24">
                <path stroke-linecap="round" stroke-linejoin="round" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"></path>
              </svg>
            </button>
          </div>
        </div>
      `;
    }).join('');

    // Attach event listeners to single check buttons
    document.querySelectorAll('.check-single-btn').forEach(btn => {
      btn.addEventListener('click', async (e) => {
        const id = btn.getAttribute('data-id');
        await checkSingleSearch(id);
      });
    });
  }

  // Render Catalog Items
  function renderCatalog() {
    if (catalogItems.length === 0) {
      catalogList.innerHTML = '<div class="text-center py-4 text-slate-400 text-sm">No items in catalog</div>';
      return;
    }

    catalogList.innerHTML = catalogItems.map(item => {
      const isIngested = ingestedIds.has(item.id);
      return `
        <div class="p-3 rounded-lg border ${isIngested ? 'border-emerald-200 bg-emerald-50/30' : 'border-slate-200 bg-white'} transition-colors flex items-center justify-between gap-3">
          <div class="min-w-0">
            <h4 class="font-semibold text-slate-900 text-sm truncate" title="${item.name}">${item.name}</h4>
            <div class="flex items-center gap-2 text-xs text-slate-500 mt-0.5">
              <span class="bg-slate-100 px-1.5 py-0.5 rounded text-[10px] font-medium uppercase tracking-wider">${item.category}</span>
              <span class="font-semibold text-slate-700">$${item.price}</span>
            </div>
          </div>

          <button data-id="${item.id}" ${isIngested ? 'disabled' : ''} 
            class="ingest-single-btn shrink-0 text-xs font-semibold py-1.5 px-3 rounded-md border transition-colors shadow-sm
              ${isIngested 
                ? 'bg-emerald-100 text-emerald-800 border-emerald-200 cursor-default' 
                : 'bg-white hover:bg-slate-50 text-slate-700 hover:text-slate-900 border-slate-300'}">
            ${isIngested ? '✓ Ingested' : 'Ingest'}
          </button>
        </div>
      `;
    }).join('');

    // Attach event listeners to ingest buttons
    document.querySelectorAll('.ingest-single-btn').forEach(btn => {
      btn.addEventListener('click', async (e) => {
        const id = btn.getAttribute('data-id');
        const item = catalogItems.find(i => i.id === id);
        if (item) {
          await ingestDocuments([item]);
        }
      });
    });
  }

  // Create Saved Search
  saveSearchForm.addEventListener('submit', async (e) => {
    e.preventDefault();

    const name = searchNameInput.value.trim();
    const q = searchQInput.value.trim();
    const category = searchCategoryInput.value.trim();
    const maxPriceVal = searchMaxPriceInput.value.trim();
    const max_price = maxPriceVal === '' ? null : parseFloat(maxPriceVal);

    if (!name) return;

    try {
      const res = await fetch('/api/saved-searches', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name, q, category, max_price })
      });

      if (!res.ok) throw new Error('Failed to create saved search');

      const newSearch = await res.json();
      savedSearches.push(newSearch);

      // Clear form
      saveSearchForm.reset();

      renderSavedSearches();
      showToast(`Saved search "${name}" created!`);
    } catch (err) {
      console.error(err);
      showToast('Failed to save search', 'error');
    }
  });

  // Check Single Saved Search
  async function checkSingleSearch(id) {
    try {
      const res = await fetch(`/api/saved-searches/${id}/check`, {
        method: 'POST'
      });

      if (!res.ok) throw new Error('Failed to check saved search');

      const updatedSearch = await res.json();
      const index = savedSearches.findIndex(s => s.id === id);
      if (index !== -1) {
        savedSearches[index] = updatedSearch;
        renderSavedSearches();
        showToast(`Checked "${updatedSearch.name}": ${updatedSearch.match_count} matches (${updatedSearch.new_count} new)`);
      }
    } catch (err) {
      console.error(err);
      showToast('Failed to check search', 'error');
    }
  }

  // Check All Saved Searches
  checkAllBtn.addEventListener('click', async () => {
    if (savedSearches.length === 0) {
      showToast('No saved searches to check', 'error');
      return;
    }

    checkAllBtn.disabled = true;
    checkAllBtn.innerHTML = `
      <svg class="animate-spin h-4 w-4 text-white" fill="none" viewBox="0 0 24 24">
        <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
        <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
      </svg>
      Checking...
    `;

    try {
      const res = await fetch('/api/check-all', {
        method: 'POST'
      });

      if (!res.ok) throw new Error('Failed to check all searches');

      savedSearches = await res.json();
      renderSavedSearches();
      showToast('All saved searches checked successfully!');
    } catch (err) {
      console.error(err);
      showToast('Failed to check all searches', 'error');
    } finally {
      checkAllBtn.disabled = false;
      checkAllBtn.innerHTML = `
        <svg class="w-4 h-4" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" d="M4 4v5h.582m15.356 2A8.001 8.001 0 1121.21 15H16"></path>
        </svg>
        Check All Searches
      `;
    }
  });

  // Ingest Documents
  async function ingestDocuments(documents) {
    try {
      const res = await fetch('/api/ingest', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ documents })
      });

      if (!res.ok) throw new Error('Failed to ingest documents');

      const data = await res.json();

      // Update local state of ingested IDs
      documents.forEach(doc => ingestedIds.add(doc.id));
      renderCatalog();

      showToast(`Successfully ingested ${data.ingested} product(s)!`);
    } catch (err) {
      console.error(err);
      showToast('Failed to ingest documents', 'error');
    }
  }

  // Ingest All Catalog Items
  ingestAllBtn.addEventListener('click', async () => {
    const uningested = catalogItems.filter(item => !ingestedIds.has(item.id));
    if (uningested.length === 0) {
      showToast('All catalog items are already ingested', 'error');
      return;
    }
    await ingestDocuments(uningested);
  });

  // Initialize
  fetchSavedSearches();
  fetchCatalog();
});

